function applyBrand(){document.title='Fletop | Cargas para tu camión';app.querySelectorAll('img[alt="Llévalo"]').forEach(image=>image.alt=brandName);const heroTitle=app.querySelector('.landing-hero h1');if(heroTitle&&heroTitle.dataset.copy!=='route'){heroTitle.innerHTML='<strong>Aprovecha tu ruta.</strong><span>Encuentra una carga para tu viaje.</span>';heroTitle.dataset.copy='route'}const walker=document.createTreeWalker(app,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode())if(node.nodeValue.includes('Llévalo'))node.nodeValue=node.nodeValue.replaceAll('Llévalo',brandName).replaceAll('lleválo','fletop')}
