const esc=s=>String(s||'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])),fmt=d=>{const date=new Date(d);return Number.isNaN(date.getTime())?'':date.toLocaleDateString('es-PE',{day:'2-digit',month:'2-digit',year:'numeric'})},fmtDateTime=d=>{const date=new Date(d);return Number.isNaN(date.getTime())?'':new Intl.DateTimeFormat('es-PE',{timeZone:'America/Lima',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(date).replace(',','')};
const api=async(p,o={})=>{const r=await fetch('/api'+p,{...o,headers:{accept:'application/json','content-type':'application/json',...(o.headers||{})}}),raw=await r.text();let d={};try{d=raw?JSON.parse(raw):{}}catch{console.error('Respuesta no JSON de la API',{url:'/api'+p,status:r.status,contentType:r.headers.get('content-type'),body:raw.slice(0,500)});throw Error(r.status===413?'La imagen es demasiado pesada para el servidor. Prueba una imagen menor a 6 MB.':'El servidor devolvió una respuesta inesperada. Inténtalo nuevamente.')};if(!r.ok)throw Error(d.error||'Ocurrió un error');return d},toast=t=>{const e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2600)};
const avatar=(n,u,cl='')=>'<span class="avatar '+cl+'">'+(u?'<img src="'+u+'" alt="Avatar" onerror="this.remove()">':'')+'<b>'+esc((n||'U')[0])+'</b></span>';
function routeView(route){const [dep,district]=String(route||'').split(' - ');return district?esc(dep)+' <em>('+esc(district)+')</em>':esc(dep)}
function cardLocation(route){const [dep,district]=String(route||'').split(' - ');return '<span class="place-department">'+esc(dep)+'</span>'+(district?'<span class="place-district">('+esc(district)+')</span>':'')}
function detailLocation(route){const [dep,district]=String(route||'').split(' - ');return '<span class="detail-department">'+esc(dep)+'</span>'+(district?'<span class="detail-district">('+esc(district)+')</span>':'')}
function peruWhatsApp(value){let number=String(value||'').replace(/\D/g,'').replace(/^0+/,'');if(number.startsWith('51'))return number;return '51'+number}
const files=f=>Promise.all([...f].slice(0,4).map(x=>new Promise(ok=>{const r=new FileReader;r.onload=()=>ok(r.result);r.readAsDataURL(x)}))),one=f=>f?new Promise(ok=>{const r=new FileReader;r.onload=()=>ok(r.result);r.readAsDataURL(f)}):Promise.resolve('');
function department(name,label,value=''){return '<label class="field">'+label+'<select name="'+name+'"><option value="">Seleccionar departamento</option>'+deps.map(x=>'<option '+(x===value?'selected':'')+'>'+x+'</option>').join('')+'</select></label>'}
function routeFields(prefix,title,value=''){let [d,x]=value.split(' - ');return '<fieldset class="place-fields"><legend>'+title+'</legend>'+department(prefix+'Department','Departamento',d||'')+'<label class="field">Distrito<select name="'+prefix+'District" '+(d?'':'disabled')+'><option value="">Seleccionar distrito</option>' +(places[d]||[]).map(y=>'<option '+(y===x?'selected':'')+'>'+y+'</option>').join('')+'</select></label></fieldset>'}
function bind(scope=app){scope.querySelectorAll('select[name$="Department"]').forEach(s=>s.onchange=()=>{const x=scope.querySelector('[name="'+s.name.replace('Department','District')+'"]');x.disabled=!s.value;x.innerHTML='<option value="">Seleccionar distrito</option>'+(places[s.value]||[]).map(y=>'<option>'+y+'</option>').join('')})}
function pack(b,k){return b[k+'Department']&&b[k+'District']?b[k+'Department']+' - '+b[k+'District']:''}
function slug(s){return String(s||'carga').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'')}
function itemUrl(l){const back=location.pathname==='/buscar'?location.pathname+location.search:'';return '/item/'+slug(l.title)+'-'+l.id+(back?'?back='+encodeURIComponent(back):'')}
function navRender(){nav.innerHTML=me?'<a class="publications nav-hide" href="/perfil">Mis publicaciones</a><a class="btn secondary account-action" href="/perfil"><i data-icon="user"></i><span>Mi cuenta</span></a><a class="btn" href="/publicar">Publicar carga</a>'+(me.role==='admin'?'<a class="admin-gear" href="/admin" title="Admin panel" aria-label="Admin panel"><i data-icon="layout-dashboard"></i></a>':'')+'<button class="exit" onclick="logout()"><i data-icon="log-out"></i><span>Salir</span></button>':'<a class="btn secondary" href="/login">Ingresar</a><a class="btn" href="/publicar">Publicar carga</a>';window.LightIcons?.render()}
function card(l){return '<article class="card '+(l.active?'':'finished')+'"><a class="card-link" href="'+itemUrl(l)+'">'+(l.images?.[0]?'<img class="cover" src="'+l.images[0]+'" alt="Foto de la carga" onerror="this.src=\'/placeholder.png\'">':'<img class="cover placeholder-img" src="/placeholder.png" alt="Carga disponible">')+'<div class="card-body">'+(!l.active?'<span class="final-tag">Anuncio finalizado</span>':'')+'<div class="card-route"><div>'+cardLocation(l.origin)+'</div><i data-icon="arrow-right"></i><div>'+cardLocation(l.destination)+'</div></div><h3>'+esc(l.title)+'</h3><div class="tags"><span class="tag"><i data-icon="scale"></i> '+esc(l.weight)+'</span><span class="tag"><i data-icon="calendar"></i> Flexible</span></div><div class="card-foot"><span class="publisher">'+avatar(l.user_name,l.user_avatar)+esc(l.user_name||'Usuario')+'</span><span class="view-cta">Ver anuncio →</span></div></div></a></article>'}
function searchForm(origin='',destination=''){return '<form class="search" id="search">'+department('origin','DESDE',origin)+department('destination','HASTA',destination)+'<button>Buscar <i data-icon="arrow-right"></i></button></form>'}
function bindSearch(){document.querySelector('#search').onsubmit=e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));if(b.origin===b.destination&&b.origin)return toast('Origen y destino deben ser distintos');navigate('/buscar?origin='+encodeURIComponent(b.origin)+'&destination='+encodeURIComponent(b.destination))}}
function viewControls(id){return '<div class="view-controls" role="group" aria-label="Vista de anuncios"><button type="button" class="active" data-view="grid" data-view-for="'+id+'" aria-label="Ver en cuadrícula"><i data-icon="grid"></i><span>Cuadrícula</span></button><button type="button" data-view="list" data-view-for="'+id+'" aria-label="Ver en lista"><i data-icon="list"></i><span>Lista</span></button></div>'}
function bindView(id){const target=document.querySelector('#'+id),buttons=[...document.querySelectorAll('[data-view-for="'+id+'"]')],saved=sessionStorage.getItem('fletop-view-'+id)||'grid';const set=view=>{target.classList.toggle('cards-list',view==='list');buttons.forEach(button=>button.classList.toggle('active',button.dataset.view===view));sessionStorage.setItem('fletop-view-'+id,view)};buttons.forEach(button=>button.onclick=()=>set(button.dataset.view));set(saved);window.LightIcons?.render()}
async function home(){app.innerHTML='<section class="landing-hero"><div class="landing-hero-content"><h1>Cargas,<br class="mobile-title-break"> directo para ti</h1>'+searchForm()+'</div></section><section class="how-section" id="como-funciona"><div class="section-intro"><h2>¿Cómo funciona?</h2><p>En pocos pasos puedes encontrar una carga que siga tu camino.</p></div><div class="steps"><article><b>01</b><div><h3>Busca una ruta</h3><p>Elige de dónde sales y a dónde quieres llegar.</p></div></article><i data-icon="arrow-right"></i><article><b>02</b><div><h3>Revisa la carga</h3><p>Confirma el peso, el espacio y los detalles.</p></div></article><i data-icon="arrow-right"></i><article><b>03</b><div><h3>Coordina directo</h3><p>Habla con el cliente y sigue avanzando.</p></div></article></div></section><section class="impact-section"><div class="section-intro"><h2>Más rutas. Más oportunidades.</h2><p>Una comunidad que conecta cargas con camioneros de todo el Perú.</p></div><div class="landing-stats"><div><i data-icon="truck"></i><p><b>Transportistas</b><span>+100 buscando carga</span></p></div><div><i data-icon="users"></i><p><b>Clientes felices</b><span>+100 cargas para llevar</span></p></div><div><i data-icon="map"></i><p><b>Encuentra una carga</b><span>No regresas vacío</span></p></div></div></section><footer class="site-footer"><section class="footer-brand"><strong><img src="/icons/logo.svg" alt="Llévalo"></strong><p>La manera simple de mover cargas y seguir avanzando.</p><div class="socials" aria-label="Redes sociales"><a href="https://www.tiktok.com" target="_blank" rel="noopener" aria-label="TikTok"><img src="/icons/tiktok.svg" alt=""></a><a href="https://www.facebook.com" target="_blank" rel="noopener" aria-label="Facebook"><img src="/icons/facebook.svg" alt=""></a><a href="https://www.instagram.com" target="_blank" rel="noopener" aria-label="Instagram"><img src="/icons/instagram.svg" alt=""></a></div><small>© 2026 Llévalo. Todos los derechos reservados.</small></section><section class="footer-links"><p>Información legal</p><a href="/terms">Términos y condiciones</a><a href="/privacy">Política de privacidad</a><a href="/data">Protección de datos</a><a href="/cookies">Política de cookies</a></section></footer>';bindSearch();window.LightIcons?.render()}
async function searchResults(q){const origin=q.get('origin')||'',destination=q.get('destination')||'',d=await api('/listings?origin='+encodeURIComponent(origin)+'&destination='+encodeURIComponent(destination)),alternatives=d.listings.length?[]:(await api('/listings')).listings,results=d.listings.map(card).join(''),alternativeMarkup=alternatives.length?'<section class="alternative-results"><div class="section-heading"><div><h2>Pero hay otras cargas disponibles</h2><p class="muted">Explora cargas activas en otras rutas.</p></div></div><div class="cards">'+alternatives.map(card).join('')+'</div></section>':'';app.innerHTML='<section class="results-search">'+searchForm(origin,destination)+'</section><section class="section results"><div class="section-heading"><div><h2>Anuncios disponibles</h2><p class="muted">'+(origin||destination?'Ruta seleccionada: '+esc(origin||'Todos')+' → '+esc(destination||'Todos'):'Explora las cargas disponibles')+'</p></div>'+viewControls('resultCards')+'</div><div class="cards" id="resultCards">'+(results||'<p class="empty">No encontramos cargas para esta ruta.</p>')+'</div>'+alternativeMarkup+'</section>';bindSearch();bindView('resultCards')}
function auth(){if(me)return navigate('/',{replace:true});const google='<a class="google" href="/auth/google">'+googleMark+'<span>Continuar con Google</span></a><div class="divider" aria-hidden="true">o</div>';app.innerHTML='<form class="auth" id="auth"><h2>Ingresar</h2><p class="muted">Accede para publicar y administrar tus cargas.</p>'+google+'<label class="field">Correo<input required name="email" type="email"></label><label class="field">Contraseña<input required name="password" type="password" minlength="6"></label><button>Ingresar</button><p class="legal"><a href="/olvido">Olvidé mi contraseña</a></p></form>';document.querySelector('#auth').onsubmit=async e=>{e.preventDefault();try{await api('/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});me=(await api('/me')).user;navRender();navigate('/perfil')}catch(x){toast(x.message)}}}
function forgot(){app.innerHTML='<form class="auth" id="forgot"><h2>Recupera tu contraseña</h2><p class="muted">Te enviaremos un enlace seguro para crear una nueva contraseña.</p><label class="field">Correo<input required name="email" type="email" autocomplete="email"></label><button>Enviar enlace</button><p class="legal"><a href="/login">Volver a iniciar sesión</a></p></form>';document.querySelector('#forgot').onsubmit=async e=>{e.preventDefault();try{const r=await api('/password/forgot',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});if(r.reset_link)modal('<h2>Enlace de desarrollo</h2><p class="muted">En producción este enlace llegará al correo registrado.</p><a class="btn block" href="'+r.reset_link+'">Restablecer contraseña</a>');else toast('Si el correo existe, recibirás un enlace de recuperación')}catch(x){toast(x.message)}}}
function reset(q){const token=q.get('token')||'';app.innerHTML='<form class="auth" id="reset"><h2>Nueva contraseña</h2><p class="muted">Elige una contraseña de al menos 6 caracteres.</p><label class="field">Nueva contraseña<input required name="password" type="password" minlength="6"></label><button>Guardar contraseña</button></form>';document.querySelector('#reset').onsubmit=async e=>{e.preventDefault();try{await api('/password/reset',{method:'POST',body:JSON.stringify({token,password:new FormData(e.target).get('password')})});toast('Contraseña actualizada');navigate('/login')}catch(x){toast(x.message)}}}
function previews(input,target,max=4){input.onchange=()=>{const list=[...input.files].slice(0,max);target.innerHTML=list.map((file,index)=>'<figure><img src="'+URL.createObjectURL(file)+'" alt="Vista previa"><button type="button" data-preview="'+index+'" aria-label="Quitar foto">×</button><figcaption>'+esc(file.name)+'</figcaption></figure>').join('');target.querySelectorAll('[data-preview]').forEach(button=>button.onclick=()=>{const kept=[...input.files].filter((_,index)=>index!==Number(button.dataset.preview)),transfer=new DataTransfer();kept.forEach(file=>transfer.items.add(file));input.files=transfer.files;input.dispatchEvent(new Event('change'))})}}
function publish(){if(!me){app.innerHTML='<div class="auth"><h2>Acceso requerido</h2><p class="muted">Para publicar una carga debes iniciar sesión.</p><a class="btn block" href="/login">Ingresar</a></div>';return}app.innerHTML='<form class="form-card wide" id="pub"><h2>Publica tu carga</h2><p class="muted">Selecciona primero el departamento y luego el distrito.</p>'+routeFields('origin','Origen')+routeFields('destination','Destino')+'<label class="field">Peso<select required name="weight"><option value="">Seleccionar</option><option>10 a 50 kg</option><option>51 a 100 kg</option><option>101 a 250 kg</option><option>251 a 500 kg</option><option>Más de 1 tonelada</option></select></label><label class="field">Título<input required name="title"></label><label class="field">Teléfono<input required name="phone"></label><label class="field">WhatsApp<input name="whatsapp"></label><label class="field">Fotos (máximo 4)<input id="photos" type="file" accept="image/*" multiple></label><div class="upload-previews" id="photoPreviews" aria-live="polite"></div><label class="field">Detalles<textarea name="details"></textarea></label><button>Publicar carga</button></form>';bind();previews(document.querySelector('#photos'),document.querySelector('#photoPreviews'));document.querySelector('#pub').onsubmit=e=>saveListing(e)}
async function saveListing(e,id){e.preventDefault();if(savingListing)return;const form=e.currentTarget,b=Object.fromEntries(new FormData(form));b.origin=pack(b,'origin');b.destination=pack(b,'destination');if(!b.origin||!b.destination)return toast('Selecciona departamento y distrito para cada punto');if(b.origin===b.destination)return toast('Origen y destino deben ser distintos');savingListing=true;const buttons=[...form.querySelectorAll('button')];buttons.forEach(button=>button.disabled=true);const submit=e.submitter||buttons[0],label=submit.textContent;submit.textContent=id?'Guardando…':'Publicando…';try{if(id){b.images=[...document.querySelectorAll('.existing-photo:not(.remove)')].map(x=>x.dataset.src);b.newImages=await files(document.querySelector('#photos').files);if(e.submitter?.value==='close')b.active=false;await api('/listings/'+id,{method:'PUT',body:JSON.stringify(b)})}else{b.images=await files(document.querySelector('#photos').files);await api('/listings',{method:'POST',body:JSON.stringify(b)})}toast(id?'Cambios guardados':'Carga publicada correctamente');navigate('/perfil')}catch(error){toast(error.message);buttons.forEach(button=>button.disabled=false);submit.textContent=label}finally{savingListing=false}}
async function listing(id){const {listing:l}=await api('/listings/'+id),mine=me?.id===l.user_id,requestedBack=new URLSearchParams(location.search).get('back'),back=requestedBack&&requestedBack.startsWith('/buscar')?requestedBack:'/';app.innerHTML='<div class="listing-shell"><a class="outside-back" href="'+esc(back)+'"><i data-icon="arrow-left"></i> Volver a explorar</a><div class="listing"><div class="info"><span class="date">Publicado el '+fmt(l.created_at)+'</span><div class="route detail-route"><div>'+detailLocation(l.origin)+'</div><i data-icon="arrow-right"></i><div>'+detailLocation(l.destination)+'</div></div><h1>'+esc(l.title)+'</h1><p>'+esc(l.details||'Carga lista para recoger.')+'</p><div class="tags"><span class="tag"><i data-icon="package"></i> '+esc(l.weight)+'</span></div><p class="publisher-detail"><b>Publicado por</b><br>'+avatar(l.user_name,l.user_avatar)+esc(l.user_name||'Usuario')+'</p><button class="secondary small" id="report"><i data-icon="flag"></i> Reportar anuncio</button></div><div class="gallery '+(l.images.length===1?'single':'')+'">'+(l.images.length?l.images.map((x,index)=>'<button class="gallery-image" type="button" data-image="'+esc(x)+'" aria-label="Ampliar foto '+(index+1)+'"><img src="'+x+'" alt="Foto de carga '+(index+1)+'" loading="lazy" onerror="this.src=\'/placeholder.png\'"></button>').join(''):'<img class="placeholder-img" src="/placeholder.png" alt="Carga disponible">')+'</div><div class="actions"><a class="btn phone-action" href="tel:'+esc(l.phone)+'"><img src="/icons/phone.svg" alt="">Llamar</a><a class="btn whats" href="https://wa.me/'+peruWhatsApp(l.whatsapp||l.phone)+'" target="_blank" rel="noopener"><img src="/icons/whatsapp.svg" alt="">WhatsApp</a><button class="btn secondary share-action" onclick="share()"><i data-icon="share"></i> Compartir</button>'+(mine?'<a class="btn secondary edit-action" href="/edit/'+l.id+'">Editar</a><button class="btn danger edit-action" id="finish">Finalizar anuncio</button>':'')+'</div></div></div>';window.LightIcons?.render();document.querySelectorAll('.gallery-image').forEach(button=>button.onclick=()=>imageModal(button.dataset.image));document.querySelector('#report').onclick=async()=>{await api('/listings/'+id+'/report',{method:'POST',body:'{}'});toast('Reporte enviado para revisión')};document.querySelector('#finish')?.addEventListener('click',async()=>{if(!confirm('¿Finalizar este anuncio?'))return;await api('/listings/'+id,{method:'PUT',body:JSON.stringify({active:false})});navigate('/perfil?tab=done');toast('Anuncio finalizado')})}
async function profile(){if(!me)return navigate('/login',{replace:true});const d=await api('/my-listings'),initial=new URLSearchParams(location.search).get('tab')==='done'?'done':'active';app.innerHTML='<div class="profile"><div class="profile-head"><span>'+avatar(me.name,me.avatar,'profile-avatar')+'<b>'+esc(me.name)+'</b></span><button class="secondary small" id="editProfile">Editar</button></div><div class="profile-toolbar"><div><h2>Mis anuncios</h2><div class="tabs"><button class="secondary small" data-tab="active">Anuncios activos</button><button class="secondary small" data-tab="done">Anuncios finalizados</button></div></div>'+viewControls('mycards')+'</div><div class="cards" id="mycards"></div></div>';const draw=t=>{document.querySelector('#mycards').innerHTML=d.listings.filter(x=>t==='active'?Boolean(x.active):!x.active).map(card).join('')||'<p class="empty">No hay anuncios en esta sección.</p>';document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===t));window.LightIcons?.render()};draw(initial);bindView('mycards');document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>navigate('/perfil?tab='+b.dataset.tab));document.querySelector('#editProfile').onclick=profileModal}
function modal(html){document.body.insertAdjacentHTML('beforeend','<div class="modal-backdrop"><div class="modal">'+html+'</div></div>');document.querySelector('.modal-backdrop').onclick=e=>{if(e.target===e.currentTarget)e.currentTarget.remove()}}
function profileModal(){const passwordFields=me.has_local_password?'<p class="muted">Solo completa estas casillas si cambiarás tu contraseña.</p><label class="field">Contraseña actual<input name="currentPassword" type="password"></label>':'<p class="muted">Crea una contraseña local para poder ingresar también con correo y contraseña.</p>';modal('<button class="modal-close" onclick="this.closest(\'.modal-backdrop\').remove()">×</button><h2>Editar mi cuenta</h2><form id="pf"><label class="field">Nombre<input name="name" required value="'+esc(me.name)+'"></label><label class="field">Correo<input name="email" required type="email" value="'+esc(me.email)+'"></label><label class="field">Avatar<input name="avatar" type="file" accept="image/*"></label><hr>'+passwordFields+'<label class="field">Nueva contraseña<input name="newPassword" type="password" minlength="6"></label><label class="field">Verificar nueva contraseña<input name="confirm" type="password"></label><button>Guardar cambios</button></form>');document.querySelector('#pf').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));if(b.newPassword!==b.confirm)return toast('Las contraseñas nuevas no coinciden');b.avatar=await one(e.target.avatar.files[0]);try{await api('/profile',{method:'PUT',body:JSON.stringify(b)});me=(await api('/me')).user;navRender();document.querySelector('.modal-backdrop').remove();profile();toast('Tu cuenta fue actualizada')}catch(x){toast(x.message)}}}
async function edit(id){const {listing:l}=await api('/listings/'+id);app.innerHTML='<form class="form-card wide" id="edit"><h2>Editar mi anuncio</h2>'+routeFields('origin','Origen',l.origin)+routeFields('destination','Destino',l.destination)+'<label class="field">Título<input name="title" value="'+esc(l.title)+'"></label><label class="field">Detalles<textarea name="details">'+esc(l.details)+'</textarea></label><label class="field">Teléfono<input name="phone" value="'+esc(l.phone)+'"></label><label class="field">WhatsApp<input name="whatsapp" value="'+esc(l.whatsapp||'')+'"></label><p class="muted">Toca una foto para marcarla y eliminarla.</p><div class="editphotos">'+l.images.map(x=>'<img class="existing-photo" data-src="'+x+'" src="'+x+'">').join('')+'</div><label class="field">Agregar fotos<input id="photos" type="file" accept="image/*" multiple></label><div class="upload-previews" id="photoPreviews" aria-live="polite"></div><button>Guardar cambios</button><button class="secondary close" value="close">Cerrar anuncio</button></form>';bind();document.querySelectorAll('.existing-photo').forEach(x=>x.onclick=()=>x.classList.toggle('remove'));previews(document.querySelector('#photos'),document.querySelector('#photoPreviews'),Math.max(0,4-l.images.length));document.querySelector('#edit').onsubmit=e=>saveListing(e,id)}
function adminTable(headers,body,empty){return '<div class="admin-table-wrap"><table class="admin-table"><thead><tr>'+headers.map(header=>'<th>'+header+'</th>').join('')+'</tr></thead><tbody>'+(body||'<tr><td class="admin-empty" colspan="'+headers.length+'">'+esc(empty)+'</td></tr>')+'</tbody></table></div>'}
function adminImage(images,alt){let source='';try{const list=Array.isArray(images)?images:JSON.parse(images||'[]');source=list?.[0]||''}catch{}return '<img class="admin-thumb" src="'+esc(source||'/placeholder.png')+'" alt="'+esc(alt||'')+'" onerror="this.src=\'/placeholder.png\'">'}
function adminStatus(active,expired=false){const label=expired?'Expirado':active?'Activo':'Finalizado';return '<span class="admin-status '+(expired?'is-expired':active?'is-active':'is-finished')+'">'+label+'</span>'}
function adminMicroButton(label,visual,handler,tone=''){return '<button type="button" class="admin-micro-action '+tone+'" aria-label="'+label+'" title="'+label+'" onclick="'+handler+'">'+visual+'</button>'}
function adminMicroLink(label,visual,href){return '<a class="admin-micro-action" aria-label="'+label+'" title="'+label+'" href="'+href+'">'+visual+'</a>'}
function adminActionLabel(label){return label.startsWith('Ver ')?'VER':label.startsWith('Editar ')?'EDITAR':label.startsWith('Desactivar ')?'OFF':label.startsWith('Activar ')?'ON':label.startsWith('Eliminar ')?'BORRAR':label}
function adminIconButton(label,icon,handler,tone=''){const state=tone||(label.startsWith('Activar ')?'is-on':label.startsWith('Desactivar ')?'is-off':'');return adminMicroButton(label,adminActionLabel(label),handler,state)}
function adminIconLink(label,icon,href){return adminMicroLink(label,adminActionLabel(label),href)}
function adminListingActions(l){const id=Number(l.id);return '<div class="admin-actions">'+adminMicroLink('Ver anuncio','VER',itemUrl(l))+(!l.expired?adminMicroButton(l.active?'Desactivar anuncio':'Activar anuncio',l.active?'OFF':'ON','toggleListing('+id+','+(!l.active)+')',l.active?'is-off':'is-on'):'')+adminMicroButton('Eliminar anuncio','BORRAR','deleteListing('+id+')','is-danger')+'</div>'}
function adminListingRow(l){return '<tr><td><span class="admin-title-cell">'+adminImage(l.images,l.title)+'<b title="'+esc(l.title)+'">'+esc(l.title)+'</b></span></td><td><span class="admin-route-cell">'+esc(l.origin||'—')+' <i data-icon="arrow-right"></i> '+esc(l.destination||'—')+'</span></td><td>'+esc(l.user_name||'No disponible')+'</td><td>'+fmtDateTime(l.created_at)+'</td><td>'+fmtDateTime(l.expires_at)+'</td><td>'+adminStatus(l.active,l.expired)+'</td><td>'+adminListingActions(l)+'</td></tr>'}
function adminReportRow(r){const listing={...r,id:r.listing_id};return '<tr><td><span class="admin-title-cell">'+adminImage(r.images,r.title)+'<b title="'+esc(r.title)+'">'+esc(r.title||'Anuncio')+'</b></span></td><td>'+esc(r.user_name||r.listing_user_name||'No disponible')+'</td><td><span class="admin-truncate" title="'+esc(r.reason||'Sin detalle')+'">'+esc(r.reason||'Sin detalle')+'</span></td><td>'+fmtDateTime(r.created_at)+'</td><td>'+adminStatus(r.active,r.expired)+'</td><td>'+adminListingActions(listing)+'</td></tr>'}
function row(l){return adminListingRow(l)}
function adminStat(label,value,icon){return '<article class="admin-stat-card"><i data-icon="'+icon+'"></i><span>'+label+'</span><b>'+value+'</b></article>'}
function setAdminNavActive(view){document.querySelectorAll('.admin-nav-item[data-v]').forEach(button=>button.classList.toggle('active',button.dataset.v===view))}
async function admin(){try{const d=await api('/admin/stats');app.innerHTML='<div class="admin admin-shell"><aside class="admin-sidebar"><div class="admin-sidebar-nav"><button class="admin-nav-item active" data-v="overview"><i data-icon="layout-dashboard"></i><span>Resumen</span></button><button class="admin-nav-item" data-v="users"><i data-icon="users"></i><span>Usuarios</span></button><button class="admin-nav-item" data-v="listings"><i data-icon="package"></i><span>Anuncios</span></button><button class="admin-nav-item" data-v="reports"><i data-icon="flag"></i><span>Anuncios reportados</span></button></div></aside><section class="admin-main" id="adminview"><header class="admin-header"><h1>Resumen</h1></header><div class="admin-dashboard-grid">'+adminStat('Total de usuarios',d.users,'users')+adminStat('Usuarios desactivados',d.inactiveUsers,'user')+adminStat('Total de anuncios',d.listings,'package')+adminStat('Reportes de anuncios',d.reports,'flag')+adminStat('Total de trabajos',d.jobs,'briefcase')+adminStat('Reportes de trabajos',d.jobReports,'flag')+'</div><div class="admin-section-title"><h2>Últimos anuncios</h2></div>'+adminTable(['Anuncio','Ruta','Publicado por','Publicado','Expira','Estado','Acciones'],d.recent.map(adminListingRow).join(''),'No hay anuncios recientes.')+'</section></div>';document.querySelectorAll('[data-v]').forEach(x=>x.onclick=()=>adminView(x.dataset.v));window.LightIcons?.render()}catch(e){toast(e.message);navigate('/',{replace:true})}}
async function adminView(v){const e=document.querySelector('#adminview');setAdminNavActive(v);if(v==='overview')return admin();if(v==='users'){const d=await api('/admin/users');users=d.users;e.innerHTML='<div class="admin-table-heading"><h1>Usuarios</h1></div>'+adminTable(['Usuario','Correo','Registro','Último acceso','Estado','Acciones'],d.users.map(u=>'<tr><td><span class="user-cell">'+avatar(u.name,u.avatar)+'<b>'+esc(u.name)+'</b>'+(u.google_connected?googleMark:'')+'</span></td><td>'+esc(u.email)+'</td><td>'+fmtDateTime(u.created_at)+'</td><td>'+(u.last_login_at?fmtDateTime(u.last_login_at):'<span class="never-login">Aún no ingresó</span>')+'</td><td>'+adminStatus(u.active)+'</td><td><div class="admin-actions">'+adminIconButton('Ver anuncios de usuario','package','viewUserListings('+u.id+')')+adminIconButton('Editar usuario','settings','editUser('+u.id+')')+'</div></td></tr>').join(''),'No hay usuarios.');window.LightIcons?.render();return}if(v==='reports'){const d=await api('/admin/reports');e.innerHTML='<div class="admin-table-heading"><h1>Anuncios reportados</h1></div>'+adminTable(['Anuncio','Publicado por','Motivo','Fecha reporte','Estado','Acciones'],d.reports.map(adminReportRow).join(''),'No hay anuncios reportados.');window.LightIcons?.render();return}let status='active';e.innerHTML='<div class="admin-table-heading"><h1>Anuncios</h1></div><div class="tabs admin-listing-tabs"><button class="secondary small active" data-listing-status="active">Anuncios activos</button><button class="secondary small" data-listing-status="finished">Anuncios finalizados</button></div><label class="field filter">Filtrar por departamento<select id="city"><option value="">Todos los departamentos</option>'+deps.map(x=>'<option>'+x+'</option>').join('')+'</select></label><div id="alist"></div>';const render=async()=>{const city=document.querySelector('#city').value,r=await api('/admin/listings?status='+status+'&city='+encodeURIComponent(city));document.querySelector('#alist').innerHTML=adminTable(['Anuncio','Ruta','Publicado por','Publicado','Expira','Estado','Acciones'],r.listings.map(adminListingRow).join(''),'No hay anuncios en esta sección.');document.querySelectorAll('[data-listing-status]').forEach(button=>button.classList.toggle('active',button.dataset.listingStatus===status));window.LightIcons?.render()};document.querySelector('#city').onchange=render;document.querySelectorAll('[data-listing-status]').forEach(button=>button.onclick=()=>{status=button.dataset.listingStatus;render()});return render()}
function editUser(id){const u=users.find(x=>String(x.id)===String(id));if(!u)return toast('No se encontró el usuario');modal('<button class="modal-close" onclick="this.closest(\'.modal-backdrop\').remove()">×</button><h2>Editar usuario</h2><form id="uf"><label class="field">Nombre<input name="name" value="'+esc(u.name)+'" required></label><label class="field">Avatar<input type="file" name="avatar" accept="image/*"></label><label class="field">Nueva contraseña <small>(opcional)</small><input name="newPassword" type="password" minlength="6"></label><label class="field">Permiso<select name="role"><option value="user" '+(u.role==='user'?'selected':'')+'>Usuario</option><option value="admin" '+(u.role==='admin'?'selected':'')+'>Administrador</option></select></label><label class="switch"><input type="checkbox" name="active" '+(u.active?'checked':'')+'> Cuenta activa</label><button>Guardar usuario</button></form>');document.querySelector('#uf').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));b.active=e.target.active.checked;b.avatar=await one(e.target.avatar.files[0]);try{await api('/admin/users/'+id,{method:'PUT',body:JSON.stringify(b)});document.querySelector('.modal-backdrop').remove();await adminView('users');toast('Usuario actualizado')}catch(error){toast(error.message)}}}
async function viewUserListings(id){const d=await api('/admin/users/'+id+'/listings'),e=document.querySelector('#adminview'),account=users.find(user=>String(user.id)===String(id));e.innerHTML='<div class="admin-subhead"><div><button class="secondary small" onclick="adminView(\'users\')">← Volver a usuarios</button><h1>Anuncios de '+esc(account?.name||'usuario')+'</h1></div><span>'+d.listings.length+' anuncio'+(d.listings.length===1?'':'s')+'</span></div>'+adminTable(['Anuncio','Ruta','Publicado por','Publicado','Expira','Estado','Acciones'],d.listings.map(adminListingRow).join(''),'Este usuario todavía no publicó anuncios.');window.LightIcons?.render()}async function toggleListing(id,active){await api('/admin/listings/'+id,{method:'PUT',body:JSON.stringify({active})});toast(active?'Anuncio activado':'Anuncio desactivado');adminView('listings')}async function deleteListing(id){if(confirm('¿Eliminar este anuncio definitivamente?')){await api('/admin/listings/'+id,{method:'DELETE'});toast('Anuncio eliminado');adminView('listings')}}function share(){if(navigator.share)navigator.share({title:'Carga en Llévalo',url:location.href});else navigator.clipboard.writeText(location.href).then(()=>toast('Enlace copiado'))}function imageModal(src){modal('<button class="modal-close" aria-label="Cerrar" onclick="this.closest(\'.modal-backdrop\').remove()">×</button><img class="image-lightbox" src="'+esc(src)+'" alt="Foto de carga ampliada">')}window.editUser=editUser;window.viewUserListings=viewUserListings;window.toggleListing=toggleListing;window.deleteListing=deleteListing;window.share=share;
const pageCopy={about:{eyebrow:'Llévalo',title:'Sobre nosotros',lead:'Conectamos a quienes tienen una carga con transportistas que pueden llevarla de forma directa y sencilla.',sections:[['Nuestra misión','Ayudar a que ningún camión vuelva vacío. Llévalo acerca oportunidades reales de carga a transportistas de todo el Perú.'],['Cómo trabajamos','Publica una carga, revisa la ruta y contacta directamente. Sin intermediarios y con información clara para tomar decisiones con tranquilidad.']]},documentation:{eyebrow:'Ayuda',title:'Documentación',lead:'Todo lo que necesitas para usar Llévalo con confianza.',sections:[['Publicar una carga','Elige origen y destino, indica el peso, agrega tus datos de contacto y publica. Puedes editar o finalizar tu anuncio cuando lo necesites.'],['Buscar cargas','Selecciona los departamentos de salida y llegada. Revisa cada anuncio y usa Llamar o WhatsApp para coordinar directamente.']]},papers:{eyebrow:'Información',title:'Papeles',lead:'Recomendaciones para realizar traslados responsables y seguros.',sections:[['Antes de coordinar','Verifica el tipo de carga, peso, ruta, horario y condiciones de entrega antes de iniciar el traslado.'],['Documentación de traslado','Acuerda con la otra parte los documentos que correspondan a la carga y conserva una copia de la conversación.']]},press:{eyebrow:'Prensa',title:'Prensa',lead:'Información y novedades de Llévalo para medios y aliados.',sections:[['Sobre Llévalo','Llévalo es una plataforma peruana que facilita el contacto directo entre clientes y transportistas.'],['Contacto de prensa','Para solicitudes de prensa o colaboraciones, escríbenos a prensa@lleválo.pe.']]},terms:{eyebrow:'Legal',title:'Términos y condiciones',lead:'Reglas simples para una comunidad segura y transparente.',sections:[['Uso de la plataforma','El usuario debe proporcionar información veraz y utilizar la plataforma únicamente para publicar o encontrar cargas.'],['Responsabilidad','Llévalo facilita el contacto entre usuarios; las condiciones del traslado se acuerdan directamente entre las partes.']]},privacy:{eyebrow:'Legal',title:'Política de privacidad',lead:'Protegemos la información que necesitas para usar Llévalo.',sections:[['Datos que usamos','Usamos tus datos de cuenta y contacto para administrar el servicio, publicar tus anuncios y permitir el contacto entre usuarios.'],['Tus decisiones','Puedes actualizar tus datos desde Mi cuenta y solicitar la eliminación de tu cuenta escribiéndonos.']]},data:{eyebrow:'Legal',title:'Protección de datos',lead:'Tratamos los datos personales de forma responsable.',sections:[['Finalidad','Los datos se usan para operar Llévalo, prevenir usos indebidos y mejorar la experiencia del servicio.'],['Seguridad','Aplicamos medidas razonables de seguridad y no vendemos tus datos personales a terceros.']]},cookies:{eyebrow:'Legal',title:'Política de cookies',lead:'Usamos solo lo necesario para que el sitio funcione.',sections:[['Cookies esenciales','Mantienen tu sesión y permiten que la plataforma recuerde acciones necesarias durante la navegación.'],['Control','Puedes administrar las cookies desde la configuración de tu navegador; algunas funciones podrían dejar de funcionar.']]}};
function jobImageModal(src){const existing=document.querySelector('.job-image-lightbox-backdrop');existing?.remove();document.body.insertAdjacentHTML('beforeend','<div class="job-image-lightbox-backdrop" role="dialog" aria-modal="true" aria-label="Imagen ampliada"><div class="job-image-lightbox"><button type="button" class="job-image-lightbox-close" aria-label="Cerrar imagen">×</button><img src="'+esc(src)+'" alt="Portada de trabajo ampliada"></div></div>');const backdrop=document.querySelector('.job-image-lightbox-backdrop');const close=()=>{backdrop.remove();document.removeEventListener('keydown',onKeydown)};const onKeydown=event=>{if(event.key==='Escape')close()};backdrop.addEventListener('click',event=>{if(event.target===backdrop)close()});backdrop.querySelector('.job-image-lightbox-close').addEventListener('click',close);document.addEventListener('keydown',onKeydown)}
function legalMarkup(source){return source.split(/\n{2,}/).map(block=>{const text=block.trim();if(!text||text.startsWith('# '))return '';if(text.startsWith('## '))return '<h2>'+esc(text.slice(3))+'</h2>';const lines=text.split('\n');if(lines.every(line=>/^[-*] /.test(line)))return '<ul>'+lines.map(line=>'<li>'+esc(line.slice(2))+'</li>').join('')+'</ul>';return '<p>'+esc(text).replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>')+'</p>'}).join('')}
async function infoPage(key){const p=pageCopy[key]||pageCopy.about;if(['terms','privacy','data','cookies'].includes(key)){try{const response=await fetch('/legal/'+key+'.md');if(!response.ok)throw Error('No se pudo cargar el documento');const source=await response.text(),title=(source.match(/^# (.+)$/m)||[])[1]||p.title;app.innerHTML='<article class="info-page legal-page"><a class="page-back" href="/"><i data-icon="arrow-left"></i> Volver al inicio</a><span class="page-eyebrow">Legal</span><h1>'+esc(title)+'</h1><div class="legal-content">'+legalMarkup(source)+'</div></article>';window.LightIcons?.render();return}catch(error){toast(error.message)}}app.innerHTML='<article class="info-page"><a class="page-back" href="/"><i data-icon="arrow-left"></i> Volver al inicio</a><span class="page-eyebrow">'+p.eyebrow+'</span><h1>'+p.title+'</h1><p class="page-lead">'+p.lead+'</p><div class="info-sections">'+p.sections.map(s=>'<section><h2>'+s[0]+'</h2><p>'+s[1]+'</p></section>').join('')+'</div></article>';window.LightIcons?.render()}
async function logout(){await api('/logout',{method:'POST'});me=null;navRender();navigate('/')}window.logout=logout;
function notFound(){app.innerHTML='<section class="not-found"><span class="page-eyebrow">Error 404</span><h1>Página no encontrada</h1><p>La dirección que buscas no existe o fue movida.</p><a class="btn" href="/">Volver al inicio</a></section>'}
function navigate(path,{replace=false}={}){const destination=path.startsWith('/')?path:'/'+path;if(replace)history.replaceState(null,'',destination);else history.pushState(null,'',destination);route();window.scrollTo({top:0,behavior:'instant'})}
async function route(){const p=decodeURIComponent(location.pathname.replace(/^\/+|\/+$/g,'')),q=new URLSearchParams(location.search),item=p.match(/^item\/.*-(\d+)$/);if(item)return listing(item[1]);if(p.startsWith('listing/'))return listing(p.split('/')[1]);if(p.startsWith('edit/'))return edit(p.split('/')[1]);if(p==='login')return auth();if(p==='register')return navigate('/login',{replace:true});if(p==='olvido')return forgot();if(p==='restablecer')return reset(q);if(p==='publish'||p==='publicar')return publish();if(p==='profile'||p==='perfil')return profile();if(p==='admin')return admin();if(p==='buscar')return searchResults(q);if(p==='como-funciona')return infoPage('documentation');if(pageCopy[p])return infoPage(p);if(!p)return home();return notFound()}(async()=>{try{me=(await api('/me')).user}catch(error){console.warn('No se pudo restaurar la sesión',error)}navRender();document.addEventListener('click',e=>{const link=e.target.closest('a[href]'),href=link?.getAttribute('href');if(!href||!href.startsWith('/')||href.startsWith('/api/')||href.startsWith('/auth/')||link.target==='_blank'||e.metaKey||e.ctrlKey)return;e.preventDefault();navigate(href)});addEventListener('popstate',route);route()})();
window.share=()=>{if(navigator.share)navigator.share({title:'Carga en Fletop',url:location.href});else navigator.clipboard.writeText(location.href).then(()=>toast('Enlace copiado'))};

const workLicenses=[['A-II-A','A-IIa'],['A-II-B','A-IIb'],['A-III-A','A-IIIa'],['A-III-B','A-IIIb'],['A-III-C','A-IIIc']],workExperience=['Sin experiencia','1 año','2 años','3 años o más'];
const legacyHome=home,legacyPublish=publish,legacyProfile=profile,legacyAdmin=admin,legacyAdminView=adminView;
const phoneDial=value=>String(value||'').replace(/[^\d+]/g,'').replace(/(?!^)\+/g,'');
function jobUrl(j){return '/trabajo/'+slug(j.title)+'-'+j.id}
function jobCover(j){return j.image||'/bg.png'}
function jobLicenseLabel(value){return Object.fromEntries(workLicenses)[value]||value}
function jobDepartment(value){const normalized=String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),escapePattern=text=>text.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),matches=deps.filter(department=>new RegExp('(^|[^a-z])'+escapePattern(department.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase())+'($|[^a-z])').test(normalized));return matches.length===1?matches[0]:''}
function workChecks(name,values,selected=[]){return '<div class="work-checks">'+values.map(item=>{const [value,label]=Array.isArray(item)?item:[item,item];return '<label><input type="checkbox" name="'+name+'" value="'+esc(value)+'" '+(selected.includes(value)?'checked':'')+'><span>'+esc(label)+'</span></label>'}).join('')+'</div>'}
function workSelect(name,label,options,value='',empty){return '<label class="field">'+label+'<span class="job-select"><select name="'+name+'"><option value="">'+empty+'</option>'+options.map(item=>{const [optionValue,optionLabel]=Array.isArray(item)?item:[item,item];return '<option value="'+esc(optionValue)+'" '+(optionValue===value?'selected':'')+'>'+esc(optionLabel)+'</option>'}).join('')+'</select><i data-icon="chevron-down"></i></span></label>'}
function money(value){const amount=Number(value);return Number.isFinite(amount)?'S/ '+new Intl.NumberFormat('es-PE',{maximumFractionDigits:2}).format(amount):''}
function workIcon(name,text){return '<span class="work-meta"><i data-icon="'+name+'"></i>'+esc(text)+'</span>'}
function jobCard(j){const lines=[workIcon('map-pin',j.location),j.licenses?.length?workIcon('truck',j.licenses.map(jobLicenseLabel).join(' · ')):'',j.experience?.length?workIcon('clock',j.experience.join(' · ')):'',j.requires_hazmat?workIcon('shield-check','Materiales peligrosos'):'',j.salary!==null&&j.salary!==undefined?workIcon('wallet',money(j.salary)):''].filter(Boolean).join('');return '<article class="job-card '+(j.active?'':'finished')+'"><a href="'+jobUrl(j)+'"><img class="job-card-cover" src="'+esc(jobCover(j))+'" alt="Portada de trabajo" loading="lazy">'+(!j.active?'<span class="final-tag">Oferta finalizada</span>':'')+'<span class="work-label"><i data-icon="briefcase"></i> Trabajo</span><h3>'+esc(j.title)+'</h3><p class="job-company">'+esc(j.employer)+'</p><div class="job-meta">'+lines+'</div><div class="job-foot"><b>Ver anuncio <i data-icon="arrow-right"></i></b></div></a></article>'}
async function workHome(){await legacyHome();const hero=app.querySelector('.landing-hero-content');if(hero&&!hero.querySelector('.work-entry')){const entry=document.createElement('a');entry.className='work-entry';entry.href='/trabajos';entry.innerHTML='<i data-icon="briefcase-business"></i><span>¿Buscas trabajo como conductor?</span><b>Ver ofertas <i data-icon="arrow-right"></i></b>';hero.append(entry);window.LightIcons?.render()}}
function publishChoice(){if(!me){app.innerHTML='<div class="auth"><h2>Acceso requerido</h2><p class="muted">Ingresa para publicar una carga o buscar un conductor.</p><a class="btn block" href="/login">Ingresar</a></div>';return}app.innerHTML='<section class="publish-choice"><span class="work-label"><i data-icon="plus-circle"></i> Publicar</span><h1>¿Qué quieres publicar?</h1><p class="muted">Elige una opción para continuar.</p><div class="publish-options"><a href="/publicar?tipo=carga"><i data-icon="package"></i><b>Una carga</b><span>Necesito transportar mercadería</span><em>Continuar <i data-icon="arrow-right"></i></em></a><a href="/publicar-trabajo"><i data-icon="briefcase"></i><b>Busco un conductor</b><span>Necesito contratar un conductor</span><em>Continuar <i data-icon="arrow-right"></i></em></a></div></section>';window.LightIcons?.render()}
function publishJobForm(job={}){if(!me){app.innerHTML='<div class="auth"><h2>Acceso requerido</h2><p class="muted">Ingresa para publicar un trabajo.</p><a class="btn block" href="/login">Ingresar</a></div>';return}const editing=Boolean(job.id),selectedDepartment=jobDepartment(job.location);app.innerHTML='<form class="form-card wide job-form" id="jobForm"><span class="work-label"><i data-icon="briefcase"></i> Trabajos para conductores</span><h2>'+ (editing?'Editar oferta de trabajo':'Publicar trabajo para conductor')+'</h2><p class="muted">Completa solo lo necesario para que un conductor pueda postular.</p><label class="field">Título del puesto *<input name="title" required maxlength="140" value="'+esc(job.title||'')+'" placeholder="Conductor de camión"></label>'+workSelect('location','Ubicación *',deps,selectedDepartment,'Seleccionar departamento')+(editing&&job.location&&!selectedDepartment?'<p class="fieldset-help">La ubicación anterior era: '+esc(job.location)+'. Selecciona el departamento correcto para actualizar esta oferta.</p>':'')+'<label class="field">Empresa *<input name="employer" required maxlength="160" value="'+esc(job.employer||'')+'" placeholder="Empresa o persona que contrata"></label><label class="field job-image-field">Portada del anuncio (opcional)<input id="jobImage" name="image" type="file" accept="image/png,image/jpeg,image/webp"><small>Puedes agregar una imagen de tu empresa, vehículo u operación. PNG, JPEG o WebP; máximo 6 MB.</small></label>'+(job.image?'<div class="job-image-preview"><img src="'+esc(job.image)+'" alt="Portada actual"><label><input id="removeJobImage" type="checkbox"> Eliminar portada</label></div>':'')+'<div class="upload-previews job-upload-preview" id="jobImagePreview" aria-live="polite"></div><fieldset><legend>Licencias aceptadas *</legend><p class="fieldset-help">Puedes marcar más de una opción.</p>'+workChecks('licenses',workLicenses,job.licenses||[])+'</fieldset><fieldset><legend>Experiencia aceptada *</legend><p class="fieldset-help">Puedes marcar más de una opción.</p>'+workChecks('experience',workExperience,job.experience||[])+'</fieldset><label class="hazmat-choice"><input name="requires_hazmat" type="checkbox" '+(job.requires_hazmat?'checked':'')+'><span><b>Autorización especial para materiales y residuos peligrosos</b><small>Márcalo solo si este puesto requiere esa autorización adicional.</small></span></label><label class="field">Sueldo (opcional)<input name="salary" type="number" min="0" step="0.01" value="'+esc(job.salary??'')+'" placeholder="2120.00"></label><label class="field">Descripción del trabajo *<textarea name="description" required maxlength="6000" placeholder="Funciones, requisitos y beneficios.">'+esc(job.description||'')+'</textarea></label><fieldset class="application-box"><legend>Contacto para postulaciones</legend><label class="field">Correo para recibir CV *<input name="application_email" required type="email" value="'+esc(job.application_email||'')+'" placeholder="seleccion@empresa.com"></label><p class="muted">Los postulantes enviarán su CV a este correo.</p><label class="field">Número de contacto (opcional)<input name="phone" inputmode="tel" maxlength="28" value="'+esc(job.phone||'')+'" placeholder="999 999 999"></label><p class="muted">Si lo incluyes, podrán escribirte por WhatsApp.</p></fieldset><button class="job-primary">'+ (editing?'Guardar cambios':'Publicar trabajo')+'</button>'+(editing?'<button class="secondary close" value="close">Finalizar oferta</button>':'')+'</form>';previews(document.querySelector('#jobImage'),document.querySelector('#jobImagePreview'),1);document.querySelector('#jobForm').onsubmit=event=>saveJob(event,job.id);window.LightIcons?.render()}
async function saveJob(event,id){event.preventDefault();const form=event.currentTarget,submitter=event.submitter,data=new FormData(form),body={title:data.get('title'),location:data.get('location'),employer:data.get('employer'),licenses:data.getAll('licenses'),experience:data.getAll('experience'),requires_hazmat:data.get('requires_hazmat')==='on',salary:data.get('salary'),description:data.get('description'),application_email:data.get('application_email'),phone:data.get('phone'),remove_image:document.querySelector('#removeJobImage')?.checked===true};const image=document.querySelector('#jobImage')?.files[0];if(image)body.image=await one(image);if(submitter?.value==='close')body.active=false;const buttons=[...form.querySelectorAll('button')];buttons.forEach(button=>button.disabled=true);try{await api(id?'/jobs/'+id:'/jobs',{method:id?'PUT':'POST',body:JSON.stringify(body)});toast(id?'Trabajo actualizado':'Trabajo publicado');navigate('/perfil?section=jobs')}catch(error){toast(error.message);buttons.forEach(button=>button.disabled=false)}}
async function jobsPage(){const filters=new URLSearchParams(location.search),params=new URLSearchParams();['location','license','experience'].forEach(key=>{const value=filters.get(key);if(value)params.set(key,value)});const result=await api('/jobs?'+params);app.innerHTML='<section class="job-search-zone"><div class="job-search-inner"><div class="job-search-title"><i data-icon="briefcase"></i><h1>Trabajo para conductor</h1></div><form id="jobFilters" class="job-filters">'+workSelect('location','Ubicación',deps,filters.get('location')||'','Todos los departamentos')+workSelect('license','Licencia',workLicenses,filters.get('license')||'','Todas las licencias')+workSelect('experience','Experiencia',workExperience,filters.get('experience')||'','Cualquier experiencia')+'</form></div></section><section class="section jobs-section"><div class="section-heading"><div><h2>Ofertas disponibles</h2><p class="muted">'+result.jobs.length+' oferta'+(result.jobs.length===1?'':'s')+' encontrada'+(result.jobs.length===1?'':'s')+'</p></div></div><div class="job-cards">'+(result.jobs.map(jobCard).join('')||'<p class="empty">No encontramos trabajos con estos filtros.</p>')+'</div></section>';const applyFilters=event=>{event?.preventDefault();const form=new FormData(document.querySelector('#jobFilters')),next=new URLSearchParams();['location','license','experience'].forEach(key=>{if(form.get(key))next.set(key,form.get(key))});navigate('/trabajos'+(next.toString()?'?'+next.toString():''))};document.querySelector('#jobFilters').onsubmit=applyFilters;document.querySelectorAll('#jobFilters select').forEach(select=>select.addEventListener('change',applyFilters));window.LightIcons?.render()}
async function jobDetail(id){
 const {job:j}=await api('/jobs/'+id),mine=me?.id===j.user_id;
 const licenses=(j.licenses||[]).map(item=>esc(jobLicenseLabel(item))).join(' · ');
 const experience=(j.experience||[]).map(item=>esc(item)).join(' · ');
 const facts=((licenses||j.requires_hazmat)?'<div class="job-fact job-fact-license"><span>Licencia</span><b>'+((licenses)||'—')+'</b>'+(j.requires_hazmat?'<small class="job-hazmat">Materiales peligrosos</small>':'')+'</div>':'')+(experience?'<div class="job-fact"><span>Experiencia</span><b>'+experience+'</b></div>':'');
 const salary=j.salary!==null&&j.salary!==undefined?'<section class="job-salary"><span>Sueldo</span><b>'+esc(money(j.salary))+'</b></section>':'';
 const cover=j.image?'<button type="button" class="job-detail-cover-button" id="jobCover" aria-label="Ver imagen completa"><img class="job-detail-cover" src="'+esc(j.image)+'" alt="Portada de trabajo"></button>':'<img class="job-detail-cover" src="/bg.png" alt="Portada de trabajo">';
 const apply='<a class="btn job-primary job-apply-primary" href="mailto:'+encodeURIComponent(j.application_email)+'?subject='+encodeURIComponent('Postulación - '+j.title)+'"><i data-icon="mail"></i><span>Enviar mi CV</span></a>';
 const whats=j.phone?'<a class="btn job-contact-action whats" target="_blank" rel="noopener" href="https://wa.me/'+peruWhatsApp(j.phone)+'"><img src="/icons/whatsapp.svg" alt="">WhatsApp</a>':'';
 const share='<button type="button" class="btn secondary job-share-action"><i data-icon="share"></i>Compartir</button>';
 const company='<section class="job-company-context"><span class="work-label">Empresa</span><p class="job-company">'+esc(j.employer)+'</p></section>';
 const publisher='<section class="job-publisher-detail"><b>Publicado por</b><span>'+avatar(j.user_name,j.user_avatar)+esc(j.user_name||'Usuario')+'</span><small>Publicado el '+fmt(j.created_at)+'</small></section>';
 app.innerHTML='<div class="job-detail-wrap"><a class="outside-back" href="/trabajos"><i data-icon="arrow-left"></i> Volver a trabajos</a><article class="job-detail">'+cover+'<h1>'+esc(j.title)+'</h1><p class="job-location"><i data-icon="map-pin"></i>'+esc(j.location)+'</p>'+company+(facts?'<section class="job-facts">'+facts+'</section>':'')+salary+'<section class="job-description"><h2>Descripción del trabajo</h2><p>'+esc(j.description).replace(/\n/g,'<br>')+'</p></section>'+publisher+'<section class="apply-box"><div><h2>¿Te interesa este trabajo?</h2><p>Envía tu CV directamente a quien publicó la oferta.</p></div><div class="job-contact-actions">'+apply+whats+share+'</div></section><button type="button" class="secondary small job-report" id="reportJob"><i data-icon="flag"></i> Denunciar</button>'+(mine?'<div class="job-owner-actions"><a class="secondary small" href="/editar-trabajo/'+j.id+'">Editar</a><button class="danger small" id="finishJob">Finalizar oferta</button></div>':'')+'</article><div class="job-mobile-actions">'+apply+whats+share+'</div></div>';
 document.querySelector('#jobCover')?.addEventListener('click',()=>jobImageModal(j.image));
 document.querySelectorAll('.job-share-action').forEach(button=>button.addEventListener('click',()=>window.shareJob(j.title)));
 document.querySelector('#reportJob').onclick=async()=>{await api('/jobs/'+j.id+'/report',{method:'POST',body:'{}'});toast('Denuncia enviada para revisión')};
 document.querySelector('#finishJob')?.addEventListener('click',async()=>{if(!confirm('¿Finalizar esta oferta?'))return;await api('/jobs/'+j.id,{method:'PUT',body:JSON.stringify({active:false})});toast('Oferta finalizada');navigate('/perfil?section=jobs&tab=done')});
 window.LightIcons?.render()
}
async function editJob(id){const {job:j}=await api('/jobs/'+id);publishJobForm(j)}
async function jobsProfile(){if(!me)return navigate('/login',{replace:true});const d=await api('/my-jobs'),tab=new URLSearchParams(location.search).get('tab')==='done'?'done':'active';app.innerHTML='<div class="profile"><div class="profile-head"><span>'+avatar(me.name,me.avatar,'profile-avatar')+'<b>'+esc(me.name)+'</b></span><button class="secondary small" id="editProfile">Editar</button></div><div class="profile-section-switch"><a class="secondary small" href="/perfil">Mis cargas</a><a class="secondary small active" href="/perfil?section=jobs">Mis trabajos</a></div><div class="profile-toolbar"><div><h2>Mis trabajos</h2><div class="tabs"><button class="secondary small" data-job-tab="active">Ofertas activas</button><button class="secondary small" data-job-tab="done">Ofertas finalizadas</button></div></div><a class="btn small" href="/publicar-trabajo">Publicar trabajo</a></div><div class="job-cards" id="myJobs"></div></div>';const draw=current=>{document.querySelector('#myJobs').innerHTML=d.jobs.filter(job=>current==='active'?job.active:!job.active).map(jobCard).join('')||'<p class="empty">No hay ofertas en esta sección.</p>';document.querySelectorAll('[data-job-tab]').forEach(button=>button.classList.toggle('active',button.dataset.jobTab===current));window.LightIcons?.render()};draw(tab);document.querySelectorAll('[data-job-tab]').forEach(button=>button.onclick=()=>navigate('/perfil?section=jobs&tab='+button.dataset.jobTab));document.querySelector('#editProfile').onclick=profileModal}
async function workProfile(){if(new URLSearchParams(location.search).get('section')==='jobs')return jobsProfile();await legacyProfile();const toolbar=app.querySelector('.profile-toolbar');if(toolbar&&!app.querySelector('.profile-section-switch')){const switcher=document.createElement('div');switcher.className='profile-section-switch';switcher.innerHTML='<a class="secondary small active" href="/perfil">Mis cargas</a><a class="secondary small" href="/perfil?section=jobs">Mis trabajos</a>';toolbar.before(switcher)}}
async function workAdmin(){await legacyAdmin();const side=app.querySelector('.admin-sidebar-nav');if(side&&!side.querySelector('[data-v="jobs"]')){const jobs=document.createElement('button');jobs.className='admin-nav-item';jobs.dataset.v='jobs';jobs.innerHTML='<i data-icon="briefcase"></i><span>Trabajos</span>';jobs.onclick=()=>adminView('jobs');const reports=document.createElement('button');reports.className='admin-nav-item';reports.dataset.v='job-reports';reports.innerHTML='<i data-icon="flag"></i><span>Trabajos reportados</span>';reports.onclick=()=>adminView('job-reports');side.append(jobs,reports);window.LightIcons?.render()}}
function adminJobRow(j){const state=j.expired?'Expirado':j.raw_active?'Activo':'Finalizado manualmente',id=Number(j.id);return '<tr><td><span class="admin-title-cell">'+(j.image?'<img class="admin-thumb" src="'+esc(j.image)+'" alt="'+esc(j.title)+'" onerror="this.src=\'/placeholder.png\'">':'<span class="admin-thumb admin-thumb-icon"><i data-icon="briefcase"></i></span>')+'<b title="'+esc(j.title)+'">'+esc(j.title)+'</b></span></td><td>'+esc(j.employer)+'</td><td>'+esc(j.location)+'</td><td>'+esc(j.user_name||'No disponible')+'</td><td>'+fmtDateTime(j.created_at)+'</td><td>'+fmtDateTime(j.expires_at)+'</td><td><span class="admin-status '+(j.expired?'is-expired':j.raw_active?'is-active':'is-finished')+'">'+state+'</span></td><td><div class="admin-actions">'+adminIconLink('Ver trabajo','arrow-up-right',jobUrl(j))+adminIconButton(j.raw_active?'Desactivar trabajo':'Activar trabajo',j.raw_active?'log-out':'plus-circle','toggleJob('+id+','+(!j.raw_active)+')')+adminIconButton('Eliminar trabajo','', 'deleteJob('+id+')','is-danger')+'</div></td></tr>'}
function jobReportRow(r){const work={id:r.job_id,title:r.title};return '<tr><td><span class="admin-title-cell">'+(r.image?'<img class="admin-thumb" src="'+esc(r.image)+'" alt="'+esc(r.title)+'" onerror="this.src=\'/placeholder.png\'">':'<span class="admin-thumb admin-thumb-icon"><i data-icon="briefcase"></i></span>')+'<b title="'+esc(r.title)+'">'+esc(r.title)+'</b></span></td><td>'+esc(r.employer||'No disponible')+'</td><td>'+esc(r.reporter_name||'No disponible')+'</td><td><span class="admin-truncate" title="'+esc(r.reason||'Contenido inapropiado')+'">'+esc(r.reason||'Contenido inapropiado')+'</span></td><td>'+fmtDateTime(r.created_at)+'</td><td><div class="admin-actions">'+adminIconLink('Ver trabajo','arrow-up-right',jobUrl(work))+'</div></td></tr>'}
async function workAdminView(v){setAdminNavActive(v);if(v==='job-reports'){const e=document.querySelector('#adminview'),d=await api('/admin/job-reports');e.innerHTML='<div class="admin-table-heading"><h1>Trabajos reportados</h1></div>'+adminTable(['Trabajo','Empresa','Reportado por','Motivo','Fecha','Acciones'],d.reports.map(jobReportRow).join(''),'No hay trabajos reportados.');window.LightIcons?.render();return}if(v!=='jobs')return legacyAdminView(v);const e=document.querySelector('#adminview');let status='active';e.innerHTML='<div class="admin-table-heading"><h1>Trabajos</h1></div><div class="tabs"><button class="secondary small active" data-job-status="active">Activas</button><button class="secondary small" data-job-status="finished">Finalizadas</button></div><div id="jobAdminList"></div>';const render=async()=>{const d=await api('/admin/jobs?status='+status);document.querySelector('#jobAdminList').innerHTML=adminTable(['Trabajo','Empresa','Ubicación','Publicado por','Publicado','Expira','Estado','Acciones'],d.jobs.map(adminJobRow).join(''),'No hay ofertas en esta sección.');document.querySelectorAll('[data-job-status]').forEach(button=>button.classList.toggle('active',button.dataset.jobStatus===status));window.LightIcons?.render()};document.querySelectorAll('[data-job-status]').forEach(button=>button.onclick=()=>{status=button.dataset.jobStatus;render()});return render()}
async function toggleJob(id,active){await api('/admin/jobs/'+id,{method:'PUT',body:JSON.stringify({active})});toast(active?'Oferta activada':'Oferta desactivada');adminView('jobs')}
async function deleteJob(id){if(confirm('¿Eliminar esta oferta definitivamente?')){await api('/admin/jobs/'+id,{method:'DELETE'});toast('Oferta eliminada');adminView('jobs')}}
function workNavRender(){nav.innerHTML=me?'<a class="publications nav-hide" href="/perfil">Mis publicaciones</a><a class="btn secondary account-action" href="/perfil"><i data-icon="user"></i><span>Mi cuenta</span></a><a class="btn" href="/publicar">Publicar</a>'+(me.role==='admin'?'<a class="admin-gear" href="/admin" title="Admin panel" aria-label="Admin panel"><i data-icon="layout-dashboard"></i></a>':'')+'<button class="exit" onclick="logout()"><i data-icon="log-out"></i><span>Salir</span></button>':'<a class="btn secondary" href="/login">Ingresar</a><a class="btn" href="/publicar">Publicar</a>';window.LightIcons?.render()}
async function workRoute(){const p=decodeURIComponent(location.pathname.replace(/^\/+|\/+$/g,'')),q=new URLSearchParams(location.search),item=p.match(/^item\/.*-(\d+)$/),work=p.match(/^trabajo\/.*-(\d+)$/);if(item)return listing(item[1]);if(work)return jobDetail(work[1]);if(p.startsWith('listing/'))return listing(p.split('/')[1]);if(p.startsWith('edit/'))return edit(p.split('/')[1]);if(p.startsWith('editar-trabajo/'))return editJob(p.split('/')[1]);if(p==='login')return auth();if(p==='register')return navigate('/login',{replace:true});if(p==='olvido')return forgot();if(p==='restablecer')return reset(q);if(p==='publish')return publishChoice();if(p==='publicar')return q.get('tipo')==='carga'?legacyPublish():publishChoice();if(p==='publicar-trabajo')return publishJobForm();if(p==='profile'||p==='perfil')return workProfile();if(p==='admin')return workAdmin();if(p==='buscar')return searchResults(q);if(p==='trabajos')return jobsPage();if(p==='como-funciona')return infoPage('documentation');if(pageCopy[p])return infoPage(p);if(!p)return workHome();return notFound()}
home=workHome;publish=publishChoice;profile=workProfile;admin=workAdmin;adminView=workAdminView;navRender=workNavRender;route=workRoute;window.toggleJob=toggleJob;window.deleteJob=deleteJob;window.shareJob=title=>{if(navigator.share)navigator.share({title:title||'Trabajo en Fletop',url:location.href});else navigator.clipboard.writeText(location.href).then(()=>toast('Enlace copiado'))};navRender();route();
